values.content:
Check this expense report against policy.

Submitter: {{ $json.submitterName || 'unknown' }}
Period: {{ $json.period || 'not specified' }}
Total: {{ $json.currency }}{{ $json.totalAmount }}

Expense policy:
{{ typeof $json.policy === 'string' ? $json.policy : ($json.policy.text || JSON.stringify($json.policy)) }}

Expense items:
{{ $json.expenseItems.map(i=>i.id+' ['+i.category+'] '+i.description+': '+i.currency+i.amount+(i.receipt?' (receipt)':' (NO RECEIPT)')+(i.vendor?' @ '+i.vendor:'')+(i.notes?' — '+i.notes:'')).join('\n') }}

Return JSON:
{"overall_verdict":"approved|approved_with_exceptions|requires_review|rejected","overall_summary":"2-3 sentences on the overall report status","approved_total":0,"flagged_total":0,"line_items":[{"id":"","status":"approved|flagged|rejected|needs_receipt|policy_ambiguous","amount":0,"issue":"specific policy issue or null if approved","policy_reference":"which policy rule applies","recommendation":"approve|reject|request_receipt|request_clarification","notes":"any additional context for approver"}],"policy_violations":[{"violation":"","items_affected":[""],"severity":"hard_block|warning|information"}],"missing_information":["what's needed to make a final determination"],"approver_note":"what the approver should tell the submitter — specific, actionable"}
